CREATE TABLE lin_lb_infohospital(InfoHospitalId INT AUTO_INCREMENT PRIMARY KEY,HospitalName VARCHAR(250),HospitalName_en VARCHAR(250),Invoice VARCHAR(250),CityId INT,Place TEXT,Adress TEXT,Tel VARCHAR(50),Fax VARCHAR(50),InfoHospitalContactId INT,CreateDt DATETIME,IsActive INT,LoginName VARCHAR(50),LoginPwd VARCHAR(50),amount DECIMAL(10,2),PayType INT NOT NULL DEFAULT 0) ENGINE=InnoDB;
CREATE TABLE lin_user(id INT AUTO_INCREMENT PRIMARY KEY,group_id INT NOT NULL DEFAULT 0,username VARCHAR(32),nickname VARCHAR(50),password VARCHAR(32),salt VARCHAR(30),email VARCHAR(100),mobile VARCHAR(11),avatar VARCHAR(255),level INT NOT NULL DEFAULT 0,gender INT NOT NULL DEFAULT 0,birthday VARCHAR(30),bio VARCHAR(100),money DECIMAL(10,2) NOT NULL DEFAULT 0,score INT NOT NULL DEFAULT 0,successions INT NOT NULL DEFAULT 0,maxsuccessions INT NOT NULL DEFAULT 0,prevtime INT,logintime INT,loginip VARCHAR(50),loginfailure INT NOT NULL DEFAULT 0,joinip VARCHAR(50),jointime INT,createtime INT,updatetime INT,token VARCHAR(50),status VARCHAR(30) NOT NULL DEFAULT 'normal',verification VARCHAR(255),openid VARCHAR(100),hospital_id INT) ENGINE=InnoDB;
CREATE TABLE lin_doctor_profile(user_id INT PRIMARY KEY,password_hash VARCHAR(100),title VARCHAR(100),qualification_files JSON,requested_hospital_id INT,review_status VARCHAR(32),review_reason VARCHAR(500),reviewed_by INT,reviewed_at DATETIME,credential_version INT NOT NULL DEFAULT 0,locked_until DATETIME,created_at DATETIME DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE lin_lb_pet(id INT AUTO_INCREMENT PRIMARY KEY,animal_name VARCHAR(100),animal_name_en VARCHAR(100),info_animal_id INT,info_variety_id INT,dict_sex_id INT,birthday VARCHAR(20),chip_no VARCHAR(50),owner_name VARCHAR(100),owner_name_en VARCHAR(100),info_hospital_id INT,IsActive INT NOT NULL DEFAULT 1,createtime INT,updatetime INT) ENGINE=InnoDB;
CREATE TABLE lin_lb_city(CityId INT PRIMARY KEY,CityName VARCHAR(100),IsActive INT DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE lin_lb_infoanimal(InfoAnimalId INT PRIMARY KEY,AnimalName VARCHAR(100),AnimalName_en VARCHAR(100),IsActive INT DEFAULT 1,createtime INT,updatetime INT) ENGINE=InnoDB;
CREATE TABLE lin_lb_infovariety(IID BIGINT PRIMARY KEY,Variety_CN VARCHAR(50),Variety_EN VARCHAR(50),createtime INT,updatetime INT) ENGINE=InnoDB;
CREATE TABLE lin_lb_dictsex(DictSexId INT PRIMARY KEY,SexName VARCHAR(50),SexName_en VARCHAR(50),IsActive INT DEFAULT 1,createtime INT,updatetime INT) ENGINE=InnoDB;
CREATE TABLE lin_lb_infosampletype(InfoSampleTypeId INT PRIMARY KEY,SampleName VARCHAR(250),SampleName_en VARCHAR(250),IsActive INT DEFAULT 1,createtime INT,updatetime INT) ENGINE=InnoDB;
CREATE TABLE lin_lb_infotesttype(InfoTestTypeId INT AUTO_INCREMENT PRIMARY KEY,TestName VARCHAR(250),TestNO VARCHAR(250),Price DOUBLE,CtoG DOUBLE,GtoC DOUBLE,DiscountReal DOUBLE,DiscountNext DOUBLE,TextModel LONGTEXT,CreateDt DATETIME,type INT,IsActive INT,createtime INT,updatetime INT) ENGINE=InnoDB;
CREATE TABLE lin_lb_infotesttype_price(IID BIGINT AUTO_INCREMENT PRIMARY KEY,InfoTestTypeid BIGINT,price DOUBLE,IsActive INT,createtime INT,updatetime INT) ENGINE=InnoDB;
CREATE TABLE lin_laboratory(id INT AUTO_INCREMENT PRIMARY KEY,code VARCHAR(64),name VARCHAR(200),description TEXT,active INT DEFAULT 1,sort_order INT DEFAULT 0,created_at DATETIME DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE lin_lab_test(id BIGINT AUTO_INCREMENT PRIMARY KEY,laboratory_id INT,test_type_id INT,price DECIMAL(18,2),active INT DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE lin_lb_listdiagnosisproject(ListDiagnosisProjectId INT AUTO_INCREMENT PRIMARY KEY,CreateDataTypeIId BIGINT,UserNO VARCHAR(250),CityId INT,InfoHospitalId INT,InfoAnimalId INT,InfoSampleTypeId INT,AnimalName VARCHAR(250),AnimalName_en VARCHAR(250),AnimalTypeId INT,AnimalType VARCHAR(250),AnimalType_en VARCHAR(250),AnimalWeight VARCHAR(250),ChipNO VARCHAR(250),Age VARCHAR(250),Birthday DATE,DictSexId INT,SampleArea VARCHAR(250),MasterName VARCHAR(250),MasterName_en VARCHAR(250),DiagnosticResults VARCHAR(250),CollectDt DATETIME,ReceiveSampleDt DATETIME,SendSampleDt DATETIME,ReportNO VARCHAR(250),SendReportDt DATETIME,TestFee DOUBLE,DeliverySendGerFee DOUBLE,DeliverySendCNFee DOUBLE,InfoCheckReceivedId INT,SaveMedium INT,IsPayMoney INT,Remark VARCHAR(250),IsSendNoticeMail INT,SampleStatus INT,DoctorName VARCHAR(250),MarketingName VARCHAR(250),CreateSampleId INT,CreateDt DATETIME) ENGINE=InnoDB;
CREATE TABLE lin_lb_diagnosisdetail(DiagnosisDetailId INT AUTO_INCREMENT PRIMARY KEY,ListDiagnosisProjectId INT,GenterNO VARCHAR(250),InfoTestTypeId INT,InfoTestTypeModelId INT,MailTitle VARCHAR(250),CreateDt DATETIME,IsChangeModelTemple INT,IsChangeMailModelTemple INT,IsSendMail INT,RealFee DOUBLE,IsCheckPass INT,PDFHttpUrl VARCHAR(500),TestPrice DECIMAL(18,2),OrginalPrice DECIMAL(18,2),OrginalDiscount DECIMAL(18,2),SendMailDt DATETIME,SendReportDt DATETIME,DetailRemark VARCHAR(250),PayStatus2 INT,DiagnosisStatus INT,IsActive INT,is_invoiced INT) ENGINE=InnoDB;
CREATE TABLE lin_lb_diagnosisdetail_info(diagnosisdetail_id INT PRIMARY KEY,MailReport LONGTEXT,ReportResult LONGTEXT) ENGINE=InnoDB;
CREATE TABLE lin_order_extension(order_id INT PRIMARY KEY,user_id INT,laboratory_id INT,user_coupon_id BIGINT,original_amount DECIMAL(18,2),discount_amount DECIMAL(18,2),payable_amount DECIMAL(18,2),settlement_mode VARCHAR(20),review_status VARCHAR(32),review_reason VARCHAR(500),reviewed_by INT,reviewed_at DATETIME) ENGINE=InnoDB;
CREATE TABLE lin_order_draft(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT,laboratory_id INT,payload JSON,version INT DEFAULT 1,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE lin_wechat_payment(id INT AUTO_INCREMENT PRIMARY KEY,payment_no VARCHAR(64) UNIQUE,order_id INT,user_id INT,hospital_id INT,amount DECIMAL(10,2),total_fee INT,status INT,transaction_id VARCHAR(64),prepay_id VARCHAR(64),pay_type VARCHAR(20),openid VARCHAR(128),trade_type VARCHAR(20),trade_state VARCHAR(20),paid_at DATETIME,create_at DATETIME,update_at DATETIME,notify_time DATETIME,body VARCHAR(255),detail VARCHAR(255),attach VARCHAR(255),out_trade_no VARCHAR(64)) ENGINE=InnoDB;
CREATE TABLE lin_recharge_order(id BIGINT AUTO_INCREMENT PRIMARY KEY,payment_no VARCHAR(64) UNIQUE,user_id INT,amount DECIMAL(18,2),request_key VARCHAR(100),status VARCHAR(32),transaction_id VARCHAR(100),created_at DATETIME DEFAULT CURRENT_TIMESTAMP,paid_at DATETIME) ENGINE=InnoDB;
CREATE TABLE lin_user_money_log(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT,money DECIMAL(18,2),`before` DECIMAL(18,2),`after` DECIMAL(18,2),memo VARCHAR(500),createtime INT) ENGINE=InnoDB;
CREATE TABLE lin_coupon(id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100),amount DECIMAL(18,2),minimum_amount DECIMAL(18,2),laboratory_id INT,starts_at DATETIME,expires_at DATETIME,active INT DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE lin_user_coupon(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT,coupon_id BIGINT,status VARCHAR(32) DEFAULT 'available',order_id INT,used_at DATETIME,created_at DATETIME DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE lin_gift(id BIGINT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(200),description TEXT,image_url VARCHAR(1000),points_cost INT,stock INT,active INT DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE lin_redemption(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT,gift_id BIGINT,gift_name VARCHAR(200),quantity INT,points_spent INT,delivery_address JSON,request_key VARCHAR(100),status VARCHAR(32) DEFAULT 'pending',tracking_number VARCHAR(100),created_at DATETIME DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uk_redemption_request(user_id,request_key)) ENGINE=InnoDB;
CREATE TABLE lin_user_score_log(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT,score INT,`before` INT,`after` INT,memo VARCHAR(500),createtime INT) ENGINE=InnoDB;
CREATE TABLE lin_article(id BIGINT AUTO_INCREMENT PRIMARY KEY,category VARCHAR(100),type VARCHAR(32),title VARCHAR(250),summary TEXT,content LONGTEXT,cover_url VARCHAR(1000),live_at DATETIME,live_url VARCHAR(1000),popup_enabled INT DEFAULT 0,status VARCHAR(32),published_at DATETIME) ENGINE=InnoDB;
CREATE TABLE lin_article_action(user_id INT,article_id BIGINT,liked INT DEFAULT 0,bookmarked INT DEFAULT 0,PRIMARY KEY(user_id,article_id)) ENGINE=InnoDB;
CREATE TABLE lin_invoice_profile(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT,title VARCHAR(200),tax_number VARCHAR(30),email VARCHAR(200),address VARCHAR(500),phone VARCHAR(50),bank_name VARCHAR(200),bank_account VARCHAR(100)) ENGINE=InnoDB;
CREATE TABLE lin_invoice_application(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT,profile_snapshot JSON,amount DECIMAL(18,2),request_key VARCHAR(100),status VARCHAR(32) DEFAULT 'pending',invoice_url VARCHAR(1000),reject_reason VARCHAR(500),issued_at DATETIME,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uk_invoice_request(user_id,request_key)) ENGINE=InnoDB;
CREATE TABLE lin_invoice_order(application_id BIGINT,order_id INT UNIQUE,PRIMARY KEY(application_id,order_id)) ENGINE=InnoDB;
CREATE TABLE lin_profile_change(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT,requested_data JSON,previous_data JSON,status VARCHAR(32) DEFAULT 'pending',review_reason VARCHAR(500),reviewed_by INT,reviewed_at DATETIME,created_at DATETIME DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE lin_user_preferences(user_id INT PRIMARY KEY,order_notifications INT DEFAULT 1,report_notifications INT DEFAULT 1,invoice_notifications INT DEFAULT 1,news_notifications INT DEFAULT 0,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE lin_sms(id BIGINT AUTO_INCREMENT PRIMARY KEY,event VARCHAR(100),mobile VARCHAR(20),code VARCHAR(10),times INT,ip VARCHAR(64),createtime INT) ENGINE=InnoDB;
CREATE TABLE lin_notification_event(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id INT,event_type VARCHAR(32),business_key VARCHAR(100),title VARCHAR(200),message VARCHAR(1000),page_path VARCHAR(300),template_data JSON,read_at DATETIME,push_status VARCHAR(32) DEFAULT 'pending',retry_count INT DEFAULT 0,next_attempt_at DATETIME,last_error VARCHAR(1000),created_at DATETIME DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uk_notification_business(user_id,event_type,business_key)) ENGINE=InnoDB;
CREATE TABLE lin_notification_delivery(id BIGINT AUTO_INCREMENT PRIMARY KEY,event_id BIGINT,status VARCHAR(32),error_code VARCHAR(100),error_message VARCHAR(1000),created_at DATETIME DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE lin_lb_notification(id BIGINT AUTO_INCREMENT PRIMARY KEY,order_id INT,new_status INT,operation_time DATETIME DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE lin_lb_notification_log(id BIGINT AUTO_INCREMENT PRIMARY KEY,notification_id BIGINT,status VARCHAR(32),created_at DATETIME DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE lin_notification_receipt(id BIGINT AUTO_INCREMENT PRIMARY KEY,event_id BIGINT,created_at DATETIME DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
